import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { isNew } from '../tagsNew';
import { t } from '../util';

/** Tiles in the strip: one row on desktop (the grid has four columns). */
const TILES = 4;

/** The first primary tags above the discussion list, glowing when something new was posted. */
export default class TagStrip extends Component {
  view() {
    const tags = app.store.all('tags').filter(tag => tag.position() !== null && !tag.isChild() && !tag.isHidden()).sort((a, b) => (a.position() ?? 0) - (b.position() ?? 0)).slice(0, TILES);
    if (!tags.length) return null;
    return m("nav", {
      className: "DuskStrip",
      "aria-label": String(t('tiles.label'))
    }, tags.map(tag => {
      const fresh = isNew(tag);
      return m(Link, {
        className: 'DuskTile' + (fresh ? ' DuskTile--new' : ''),
        href: app.route('tag', {
          tags: tag.slug()
        }),
        style: {
          '--tag-color': tag.color() || 'var(--primary-color)'
        }
      }, m("span", {
        className: "DuskTile-icon"
      }, tag.icon() ? m(Icon, {
        name: tag.icon()
      }) : m(Icon, {
        name: "fas fa-hashtag"
      })), m("span", {
        className: "DuskTile-name"
      }, tag.name()), fresh ? m("span", {
        className: "DuskTile-new"
      }, t('tiles.new')) : null, m("span", {
        className: "DuskTile-count"
      }, t('tiles.discussions', {
        count: tag.discussionCount() || 0
      })));
    }));
  }
}
flarum.reg.add('ernestdefoe-duskline', 'forum/components/TagStrip', TagStrip);