import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import { rankName, standing } from '../renown';
import { t } from '../util';

/** Progress to the next Renown level (only with Renown). */
export default class XpPanel extends Component {
  view() {
    const s = standing(this.attrs.user);
    if (!s) return null;
    const fmt = n => n.toLocaleString(app.translator.getLocale() || undefined);
    return m("div", {
      className: "DuskXp"
    }, m("div", {
      className: "DuskXp-row"
    }, m("span", {
      className: "DuskXp-label"
    }, s.step ? t('xp.next', {
      level: s.level + 1
    }) : t('xp.max')), m("span", {
      className: "DuskXp-value"
    }, s.step ? t('xp.progress', {
      into: fmt(s.into),
      step: fmt(s.step)
    }) : rankName(s.rank))), m("div", {
      className: "DuskXp-bar",
      role: "progressbar",
      "aria-valuemin": 0,
      "aria-valuemax": 100,
      "aria-valuenow": s.pct,
      "aria-label": String(t('xp.label'))
    }, m("span", {
      style: {
        width: s.pct + '%'
      }
    })));
  }
}
flarum.reg.add('ernestdefoe-duskline', 'forum/components/XpPanel', XpPanel);