import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import { RANKS, rankName, rankStart, standing } from '../renown';
import { t } from '../util';

/** Stops shown on the road: the current rank with up to three either side. */
const STOPS = 7;

/** Renown's ranks as a road, above a member's posts. */
export default class RankRoad extends Component {
  view() {
    const user = this.attrs.user;
    const s = standing(user);
    if (!s) return null;
    const first = Math.max(1, Math.min(s.rank - 3, RANKS - STOPS + 1));
    const ranks = Array.from({
      length: STOPS
    }, (_, i) => first + i);
    const done = ranks.indexOf(s.rank);
    let renownHref = null;
    try {
      renownHref = app.route('user.renown', {
        username: user.slug()
      });
    } catch {
      renownHref = null; // A Renown without its profile tab.
    }
    return m("section", {
      className: "DuskRoad"
    }, m("div", {
      className: "DuskRoad-head"
    }, m("h3", {
      className: "DuskRoad-title"
    }, t('road.title')), m("span", {
      className: "DuskRoad-note"
    }, s.rank < RANKS ? t('road.to_next', {
      count: rankStart(s.rank + 1) - s.level,
      rank: rankName(s.rank + 1)
    }) : t('road.top')), renownHref ? m(Link, {
      className: "DuskRoad-all",
      href: renownHref
    }, t('road.all')) : null), m("ol", {
      className: "DuskRoad-track",
      style: {
        '--done': done / (STOPS - 1)
      }
    }, ranks.map(rank => m("li", {
      className: 'DuskRoad-stop' + (rank < s.rank ? ' is-done' : rank === s.rank ? ' is-current' : ''),
      "aria-current": rank === s.rank ? 'step' : undefined
    }, m("i", {
      "aria-hidden": "true"
    }), m("span", null, rankName(rank))))));
  }
}
flarum.reg.add('ernestdefoe-duskline', 'forum/components/RankRoad', RankRoad);