import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import Sky from './components/Sky';
import DuskHero from './components/DuskHero';
import { addClass, cfg, mergeStyle, t } from './util';
/** A discussion's first tag that has a color: its glow. */
const tagColor = discussion => {
  const tags = discussion.tags?.() || [];
  return tags.find(tag => tag?.color?.())?.color() || null;
};

/** Sky + glow behind a core hero; the glow takes the tag's color, else the accent. */
function skyBehind(vdom, glow) {
  if (!vdom?.attrs) return;
  addClass(vdom.attrs, 'DuskSkyHero');
  mergeStyle(vdom.attrs, {
    '--dusk-glow': glow || 'var(--dusk-accent)'
  });
}
const skyItems = items => {
  items.add('duskSky', m(Sky, {
    uid: "hero",
    className: "DuskSky--hero"
  }), 200);
  items.add('duskGlow', m("div", {
    className: "DuskSkyHero-glow",
    "aria-hidden": "true"
  }), 190);
};

/** Author, replies and, for members, how far they have read. */
function discussionMeta(discussion) {
  const author = discussion.user();
  const posts = (discussion.lastPostNumber() ?? discussion.commentCount()) || 1;
  const read = app.session.user ? Math.min(discussion.lastReadPostNumber() || 0, posts) : 0;
  const pct = Math.round(read / posts * 100);
  return m("div", {
    className: "DuskSkyHero-meta"
  }, author ? m(Link, {
    className: "DuskSkyHero-author",
    href: app.route.user(author)
  }, m(Avatar, {
    user: author
  }), m("span", null, t('hero.by', {
    name: author.displayName()
  }))) : null, m("span", {
    className: "DuskSkyHero-stat"
  }, t('hero.replies', {
    count: discussion.replyCount() || 0
  })), app.session.user ? m("span", {
    className: "DuskSkyHero-progress",
    title: String(t('hero.read', {
      read,
      total: posts
    }))
  }, m("span", {
    className: "DuskSkyHero-progressBar",
    style: {
      width: pct + '%'
    }
  }), m("span", {
    className: "DuskSkyHero-progressText"
  }, t('hero.read', {
    read,
    total: posts
  }))) : null);
}
export default function heroes() {
  // The discussion hero.
  extend('flarum/forum/components/DiscussionHero', 'view', function (vdom) {
    if (cfg()?.hero !== 'off') skyBehind(vdom, tagColor(this.attrs.discussion));
  });
  extend('flarum/forum/components/DiscussionHero', 'viewItems', function (items) {
    if (cfg()?.hero !== 'off') skyItems(items);
  });
  extend('flarum/forum/components/DiscussionHero', 'items', function (items) {
    if (cfg()?.hero !== 'off') items.add('duskMeta', discussionMeta(this.attrs.discussion), -20);
  });

  // A tag's page.
  extend('ext:flarum/tags/forum/components/TagHero', 'view', function (vdom) {
    if (cfg()?.hero !== 'off') skyBehind(vdom, this.attrs.model?.color?.() || null);
  });
  extend('ext:flarum/tags/forum/components/TagHero', 'viewItems', function (items) {
    if (cfg()?.hero !== 'off') skyItems(items);
  });

  // The Tags page: a compact sky header instead of the welcome banner.
  override('ext:flarum/tags/forum/components/TagsPage', 'hero', function (original) {
    if (!cfg() || cfg().hero === 'off') return original();
    const count = app.store.all('tags').filter(tag => !tag.isHidden()).length;
    return m(DuskHero, {
      compact: true,
      title: String(t('hero.tags_title')),
      message: String(t('hero.tags_count', {
        count
      }))
    });
  });
}