import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Sky from './Sky';
import { cfg, currentScene, motionOk, saveData, startDiscussion, t } from '../util';

/**
 * The index hero: the sky (or the admin's picture or video), the welcome text and
 * Start a discussion. With a title it is the compact header of another page.
 */
export default class DuskHero extends Component {
  view() {
    const own = typeof this.attrs.title === 'string';
    const c = cfg();
    const scene = currentScene();
    const video = c.hero === 'video' && c.video && motionOk() && !saveData();
    let media;
    if (c.hero === 'image' && c.image) media = m("img", {
      className: "DuskHero-media",
      src: c.image,
      alt: ""
    });else if (video) media = m("video", {
      className: "DuskHero-media",
      src: c.video,
      poster: c.image || undefined,
      autoplay: true,
      muted: true,
      loop: true,
      playsinline: true,
      "aria-hidden": "true"
    });else if (c.hero === 'video' && c.image) media = m("img", {
      className: "DuskHero-media",
      src: c.image,
      alt: ""
    });else media = m(Sky, {
      uid: "hero"
    });
    const canStart = !own && (!app.session.user || app.forum.attribute('canStartDiscussion'));
    return m("header", {
      className: 'Hero DuskHero' + (this.attrs.compact ? ' DuskHero--compact' : '')
    }, media, m("div", {
      className: "DuskHero-shade"
    }), m("div", {
      className: "container DuskHero-content"
    }, c.hero === 'clock' && !own ? m("span", {
      className: "DuskHero-chip"
    }, m(Icon, {
      name: "far fa-clock"
    }), t(`scene.${scene}`)) : null, m("h1", {
      className: "DuskHero-title"
    }, own ? this.attrs.title : app.forum.attribute('welcomeTitle')), m("div", {
      className: "DuskHero-message"
    }, own ? this.attrs.message : m.trust(app.forum.attribute('welcomeMessage') || '')), canStart ? m("div", {
      className: "DuskHero-actions"
    }, m(Button, {
      className: "Button Button--primary DuskHero-start",
      icon: "fas fa-plus",
      onclick: startDiscussion
    }, app.translator.trans('core.forum.index.start_discussion_button'))) : null));
  }
}
flarum.reg.add('ernestdefoe-duskline', 'forum/components/DuskHero', DuskHero);